import React from "react";

import "./styles/merchant-products.css"

import {
  BrowserRouter,
  Navigate,
  Route,
  Routes,
} from "react-router-dom";

import {
  AuthProvider,
  useAuth,
} from "./context/AuthContext.js";

import MerchantProducts from "./pages/MerchantProducts.js";
import LandingPage from "./pages/LandingPage.js";
import Login from "./pages/Login.js";
import RegisterAccount from "./pages/RegisterAccount.js";
import RegisterStore from "./pages/RegisterStore.js";
import ForgotPassword from "./pages/ForgotPassword.js";
import ResetPassword from "./pages/ResetPassword.js";
import Dashboard from "./pages/Dashboard.js";

const ProtectedRoute = ({ children }) => {
  const {
    token,
    user,
  } = useAuth();

  if (!token) {
    return (
      <Navigate
        to="/login"
        replace
      />
    );
  }

  if (!user?.tenant) {
    return (
      <Navigate
        to="/register-store"
        replace
      />
    );
  }

  return children;
};

const StoreSetupRoute = ({ children }) => {
  const {
    token,
    user,
  } = useAuth();

  if (!token) {
    return (
      <Navigate
        to="/login"
        replace
      />
    );
  }

  if (user?.tenant) {
    return (
      <Navigate
        to="/dashboard"
        replace
      />
    );
  }

  return children;
};

const PublicRoute = ({ children }) => {
  const {
    token,
    user,
  } = useAuth();

  if (!token) {
    return children;
  }

  if (!user?.tenant) {
    return (
      <Navigate
        to="/register-store"
        replace
      />
    );
  }

  return (
    <Navigate
      to="/dashboard"
      replace
    />
  );
};

const RecoveryRoute = ({ children }) => {
  return children;
};

function AppRoutes() {
  return (
    <Routes>
      <Route
        path="/"
        element={<LandingPage />}
      />

      <Route
        path="/login"
        element={
          <PublicRoute>
            <Login />
          </PublicRoute>
        }
      />

      <Route
        path="/register-account"
        element={
          <PublicRoute>
            <RegisterAccount />
          </PublicRoute>
        }
      />

      <Route
        path="/forgot-password"
        element={
          <RecoveryRoute>
            <ForgotPassword />
          </RecoveryRoute>
        }
      />

      <Route
        path="/reset-password/:token"
        element={
          <RecoveryRoute>
            <ResetPassword />
          </RecoveryRoute>
        }
      />

      <Route
        path="/register-store"
        element={
          <StoreSetupRoute>
            <RegisterStore />
          </StoreSetupRoute>
        }
      />

      <Route
        path="/dashboard"
        element={
          <ProtectedRoute>
            <Dashboard />
          </ProtectedRoute>
        }
      />

      <Route
        path="/merchant/products"
        element={
          <ProtectedRoute>
            <MerchantProducts />
          </ProtectedRoute>
        }
      />

      <Route
        path="*"
        element={
          <Navigate
            to="/"
            replace
          />
        }
      />
    </Routes>
  );
}

function App() {
  return (
    <AuthProvider>
      <BrowserRouter>
        <AppRoutes />
      </BrowserRouter>
    </AuthProvider>
  );
}

export default App;
